(13, 'sms', 'appointment_reminder', 0, 'Evening reminder to customer about next day appointment (requires cron setup)', '', 'Dear {client_name}.\nWe would like to remind you that you have booked {service_name} tomorrow at {appointment_time}. We are waiting for you at {company_address}.\nThank you for choosing our company.\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":1,\"perform\":\"before\",\"at_hour\":18,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":-24}'),
(14, 'voice', 'appointment_reminder', 0, 'Evening reminder to customer about next day appointment (requires cron setup)', '', 'Dear {client_name}.\nWe would like to remind you that you have booked {service_name} tomorrow at {appointment_time}. We are waiting for you at {company_address}.\nThank you for choosing our company.\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":1,\"perform\":\"before\",\"at_hour\":18,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":-24}'),
(15, 'sms', 'appointment_reminder', 0, 'Follow-up message in the same day after appointment (requires cron setup)', '', 'Dear {client_name}.\nThank you for choosing {company_name}. We hope you were satisfied with your {service_name}.\nThank you and we look forward to seeing you again soon.\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":21,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(16, 'sms', 'staff_day_agenda', 0, 'Evening notification with the next day agenda to staff member (requires cron setup)', '', 'Hello.\nYour agenda for tomorrow is:\n{next_day_agenda}', 1, 0, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":18,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":-24}'),
(17, 'email', 'verify_email', 1, 'Notification to customer with verification code', 'Bookly verification code', '{verification_code}', 0, 1, 0, 0, NULL, 0, 0, 0, '[]'),
(18, 'sms', 'verify_phone', 1, 'Notification to customer with verification code', '', '{verification_code}', 0, 1, 0, 0, NULL, 0, 0, 0, '[]'),
(19, 'email', 'mobile_sc_grant_access_token', 1, 'New staff member\'s Bookly Staff Cabinet mobile app access token details', 'Your Bookly Staff Cabinet mobile app access token', 'Hello,\n\nTo log in to the Bookly Staff Cabinet mobile app, please use the following link:\n{access_token_link}\n\nIf the link does not work, you can manually enter this access token in the app:\n{access_token}', 1, 0, 0, 0, NULL, 0, 0, 0, '[]'),
(20, 'sms', 'mobile_sc_grant_access_token', 1, 'New staff member\'s Bookly Staff Cabinet mobile app access token details', '', 'Hello,\n\nTo log in to the Bookly Staff Cabinet mobile app, please use the following link:\n{access_token_link}\n\nIf the link does not work, you can manually enter this access token in the app:\n{access_token}', 1, 0, 0, 0, NULL, 0, 0, 0, '[]');
