INSERT INTO `dp5_bookly_shop` (`id`, `plugin_id`, `highlighted`, `priority`, `demo_url`, `title`, `slug`, `description`, `url`, `icon`, `image`, `price`, `sub_price`, `sales`, `rating`, `reviews`, `published`, `seen`, `license`, `content`, `bundle_plugins`, `visible`, `created_at`) VALUES
(1, 20251111, 1, 100, '', 'Bookly Ultimate', 'bookly-bundle-ultimate', '', 'https://www.booking-wp-plugin.com/pricing/', 'https://cloud.bookly.pro/public_resources/images/bookly-bundle-ultimate.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-bundle-ultimate.png', 0.00, NULL, 0, 0.00, 0, '2017-07-01 01:42:24', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"The complete Bookly experience \\u2014 every add-on, every feature, all in one.\\r\\nBookly Ultimate Bundle includes Bookly Pro and all existing Bookly add-ons, unlocking the full potential of the platform.\\r\\nEnjoy unlimited flexibility to automate online booking, manage complex schedules, process payments, handle customer relations, and integrate with any workflow \\u2014 the most powerful version of Bookly ever made.\",\"badge\":\"ALL-IN\",\"short\":\"Everything you need to scale, with every add-on included.\",\"features\":[{\"body\":\"All 47 add-ons, and every one released while your license is active \\u2014 nothing to buy separately later.\",\"title\":\"Every add-on included\"},{\"body\":\"Ten gateways: Stripe, Square, both PayPal flows, Authorize.Net, 2Checkout, Mollie, Payson and PayU for Latin America and India.\",\"title\":\"More payment options\"},{\"body\":\"One license across a WordPress network, and venues with their own staff, hours and prices.\",\"title\":\"Multiple sites & locations\"},{\"body\":\"Customer groups and cabinets, ratings, invoices, taxes, gift cards, packages and waiting lists.\",\"title\":\"The full customer management toolkit\"}],\"footnote\":\"Every add-on, plus future releases\",\"adds_suffix\":\" & priority support\",\"inherit\":\"Everything in Bookly Business\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":199,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":20,\"amount\":499,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":100,\"amount\":699,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":159,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":20,\"amount\":249,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":100,\"amount\":299,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]}}}', '[7226091,13903524,15552320,17328208,17367838,17457141,17956131,18611122,18704535,18874038,19497634,19617518,20005540,20685954,20917406,20952783,21113698,21113750,21113860,21113970,21114042,21114096,21114146,21344225,21344290,21344354,21574371,21574466,21574566,21841764,21841828,21841856,21841871,22060579,22060627,22060703,22060797,22999600,22999632,23324001,23350952,24219988,29936495,34925755,20250716,20260727,20260519,20260518]', 1, '2026-10-11 06:59:23'),
(2, 7226091, 1, 100, 'https://www.booking-wp-plugin.com/demo/1/', 'Bookly Pro', 'bookly-addon-pro', '', 'https://www.booking-wp-plugin.com/pricing/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-pro.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-pro.jpg', 0.00, NULL, 0, 0.00, 0, '2014-04-12 17:14:52', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bring appointment scheduling process to the next level with Bookly Pro (Add-on). Pro version turns Bookly plugin into the professional appointment management system. Unlock Advanced Customer management, Service provider management, Services management, Email and SMS notifications, Booking management capabilities. Connect payment gateways and modify Pro version with other add-ons available only with Bookly Pro and more.\",\"badge\":\"Core\",\"short\":\"The essentials for running your bookings with ease.\",\"inherit\":\"Everything you need for professional booking\",\"features\":[{\"body\":\"Every customer in one list, with their booking history, contact details and notes.\",\"title\":\"Customer management\"},{\"body\":\"Staff with their own working hours, services and days off \\u2014 each booking goes to the right person.\",\"title\":\"Staff & service providers\"},{\"body\":\"Services grouped into categories, each with its own duration, price and capacity.\",\"title\":\"Services & categories\"},{\"body\":\"Confirmations, reminders and follow-ups sent automatically, on templates you write yourself.\",\"title\":\"Email & SMS notifications\"}],\"footnote\":\"The foundation for Bookly add-ons\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":99,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]}}}', NULL, 1, '2026-10-11 06:59:23'),
(3, 20251110, 2, 100, '', 'Bookly Business', 'bookly-bundle-business', '', 'https://www.booking-wp-plugin.com/pricing/', 'https://cloud.bookly.pro/public_resources/images/bookly-bundle-business.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-bundle-business.png', 0.00, NULL, 0, 0.00, 0, '2026-11-01 05:48:16', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"All-in-one booking solution for growing businesses.\\r\\nBookly Business Bundle includes Bookly Pro and 16 powerful add-ons to help you manage appointments, teams, payments, and schedules more efficiently.\\r\\nGet advanced tools for custom booking forms, recurring appointments, staff management, online payments, special schedules, and more \\u2014 everything you need to run your business smoothly with Bookly.\",\"badge\":\"Most popular\",\"short\":\"For growing teams that need more ways to book, pay, and manage.\",\"features\":[{\"body\":\"Custom fields, paid extras and durations of your own, so the form collects everything before the visit.\",\"title\":\"Advanced booking forms\"},{\"body\":\"Stripe and PayPal, with deposits when you take part of the price upfront and coupons when you give a discount.\",\"title\":\"Online payments at booking\"},{\"body\":\"Weekly or monthly repeats in one booking, and several attendees on a single time slot.\",\"title\":\"Recurring & group bookings\"},{\"body\":\"Individual schedules, holidays and exceptions, plus two-way sync with Google, Outlook and Apple calendars.\",\"title\":\"Staff schedules & calendars\"}],\"footnote\":\"%d add-ons in total, incl. Bookly Pro\",\"inherit\":\"Everything in Bookly Pro\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":129,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":5,\"amount\":249,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":69,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":5,\"amount\":129,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]}}}', '[7226091,21113970,21344225,21114146,15552320,22060579,18874038,17328208,18611122,20005540,21113860,22060627,19497634,17956131,21841764,19617518,22060703,23350952,20260727]', 1, '2026-10-11 06:59:23'),
(4, 34925755, 0, 0, '', 'Mailchimp', 'bookly-addon-mailchimp', '', 'https://www.booking-wp-plugin.com/add-ons/mailchimp-integration/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-mailchimp.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-mailchimp.jpg', 0.00, NULL, 0, 0.00, 0, '2021-11-24 03:10:56', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Mailchimp (Add-on) offers a seamless integration between your Bookly booking system and your Mailchimp account, one of the most popular email marketing platforms available. With this integration, you can easily automate your email campaigns and build strong relationships with your customers. New customers in Bookly will be automatically added as new subscribers to your Mailchimp mailing list, allowing you to easily deliver targeted messages that drive sales and engagement.\",\"tags\":[\"Marketing\",\"Integrations\",\"Automation\"],\"short\":\"Sync customers into your Mailchimp audience.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:23'),
(5, 29936495, 0, 0, 'https://www.booking-wp-plugin.com/demo/full/wp-admin/admin.php?page=bookly-discounts', 'Discounts', 'bookly-addon-discounts', '', 'https://www.booking-wp-plugin.com/add-ons/offer-conditional-discounts/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-discounts.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-discounts.jpg', 0.00, NULL, 0, 0.00, 0, '2021-01-05 01:18:25', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Providing discounts is a proven method to attract customers and boost sales. Bookly Discounts (Add-on) enables you to create automatic conditional discounts based on various factors like the number of customers or services booked. Once the booking details meet the conditions you set, the discounted price will be automatically applied, and customers will see the reduced price instantly.\",\"tags\":[\"Marketing\",\"Payments\",\"Automation\"],\"short\":\"Rule-based price cuts for services and periods.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(6, 24219988, 0, 0, '', 'PayPal Checkout', 'bookly-addon-paypal-checkout', '', 'https://www.booking-wp-plugin.com/add-ons/paypal-checkout-payments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-paypal-checkout.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-paypal-checkout.jpg', 0.00, NULL, 0, 0.00, 0, '2019-07-30 18:31:46', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly PayPal Checkout (Add-on) provides you with the ability to accept secure online payments at the time of booking through one of the most popular payment gateways. With this add-on, you can seamlessly integrate the PayPal payment option into your Bookly PRO booking form. By offering this convenient payment option to your customers, they can easily purchase your services with just a few clicks.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"The current PayPal flow, on-site and mobile ready.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(7, 23350952, 0, 0, '', 'Outlook Calendar', 'bookly-addon-outlook-calendar', '', 'https://www.booking-wp-plugin.com/add-ons/outlook-calendar-sync/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-outlook-calendar.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-outlook-calendar.jpg', 0.00, NULL, 0, 0.00, 0, '2019-02-21 23:33:34', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Outlook Calendar (Add-on) enables a complete bidirectional synchronization between Bookly Calendar and Outlook Calendar, ensuring seamless management of appointments across both platforms. With this add-on, appointments made through Bookly will be automatically added to the linked Outlook Calendar, while updates, cancellations, and new events from Outlook Calendar will be immediately reflected in Bookly.\",\"tags\":[\"Calendar & Sync\",\"Integrations\"],\"short\":\"Keep Outlook and Bookly schedules in step.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":49,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":15.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(8, 23324001, 0, 0, 'https://www.booking-wp-plugin.com/demo/custom-statuses/', 'Custom Statuses', 'bookly-addon-custom-statuses', '', 'https://www.booking-wp-plugin.com/add-ons/use-custom-statuses/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-custom-statuses.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-custom-statuses.jpg', 0.00, NULL, 0, 0.00, 0, '2019-02-18 20:10:01', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"If you need to manage your online bookings more efficiently and want to assign custom labels to your Bookly appointments, you can use Bookly Custom Statuses (Add-on). When editing an appointment, you can select a custom status from the list you created, allowing you to add more specific information to the appointment. You can also set up email notifications that correspond to each custom appointment status.\",\"tags\":[\"Staff & Teams\",\"Automation\"],\"short\":\"Model your own workflow beyond the defaults.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(9, 22999632, 0, 0, 'https://www.booking-wp-plugin.com/demo/collaborative-services/', 'Collaborative Services', 'bookly-addon-collaborative-services', '', 'https://www.booking-wp-plugin.com/add-ons/share-rooms-equipment-employees/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-collaborative-services.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-collaborative-services.jpg', 0.00, NULL, 0, 0.00, 0, '2018-12-12 00:22:29', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do you offer services that involve two or more staff members working together or shared resources? With the Bookly Collaborative Services (Add-on), you can create and sell complex services that involve multiple employees and resources, while your clients easily book a single service they need. Whether your employees work together to provide a service or need to use shared resources in an appointment, Bookly will make sure everything is properly scheduled.\",\"tags\":[\"Staff & Teams\",\"Booking form\"],\"short\":\"Several providers on one appointment.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(10, 22999600, 0, 0, 'https://www.booking-wp-plugin.com/demo/tasks/', 'Tasks', 'bookly-addon-tasks', '', 'https://www.booking-wp-plugin.com/add-ons/unlimited-list-tasks/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-tasks.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-tasks.jpg', 0.00, NULL, 0, 0.00, 0, '2018-12-12 00:17:51', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Tasks (Add-on) offers a solution for businesses that provide services without requiring clients to select a specific day and time. With this feature, clients and administrators can create and manage a list of tasks or unscheduled appointments within the Bookly admin area. For instance, employees can set a task to arrange a meeting with a specific client, and once it\\u2019s done, they can schedule the date and time, which will automatically convert the task into an appointment.\",\"tags\":[\"Staff & Teams\",\"Automation\"],\"short\":\"Assign and track work around each appointment.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(11, 22060797, 0, 0, '', 'PayUbiz', 'bookly-addon-payu-biz', '', 'https://www.booking-wp-plugin.com/add-ons/payubiz/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-payu-biz.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-payu-biz.jpg', 0.00, NULL, 0, 0.00, 0, '2018-06-06 04:52:32', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"If you want to accept and manage online payments from your clients in India, PayUbiz is a popular payment gateway that can help. With the Bookly PayUbiz (Add-on), you can easily integrate PayUbiz method into your Bookly PRO booking form and offer your customers a convenient way to pay instantly for their appointments.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"Card payments in India through PayUbiz.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(12, 22060703, 0, 0, 'https://www.booking-wp-plugin.com/demo/custom-duration/', 'Custom Duration', 'bookly-addon-custom-duration', '', 'https://www.booking-wp-plugin.com/add-ons/time-flexible-services/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-custom-duration.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-custom-duration.jpg', 0.00, NULL, 0, 0.00, 0, '2018-06-06 04:42:30', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Custom Duration (Add-on) allows your clients to have more control over their bookings by choosing how long they would like their appointments to last. This feature is especially useful for services that may require more time than the default duration, such as meetings or conferences. When clients book services with flexible duration, they can select the length of their appointment at the beginning of the booking process in the Bookly form, and the price will be calculated accordingly.\",\"tags\":[\"Booking form\",\"Payments\"],\"short\":\"Let customers choose how long a session runs.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(13, 22060627, 0, 0, 'https://www.booking-wp-plugin.com/demo/customer-cabinet/', 'Customer Cabinet', 'bookly-addon-customer-cabinet', '', 'https://www.booking-wp-plugin.com/add-ons/personal-customer-cabinet/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-customer-cabinet.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-customer-cabinet.jpg', 0.00, NULL, 0, 0.00, 0, '2018-06-06 04:39:24', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Looking for a way to provide your clients with online access to their bookings? Bookly Customer Cabinet (Add-on) allows you to set up a secure, personal customer account on your website where clients can view and manage their appointments and profile information. This includes the ability to reschedule and cancel appointments, view payments, and update personal information.\",\"tags\":[\"Customers\",\"Automation\"],\"short\":\"Let customers reschedule and cancel themselves.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(14, 22060579, 0, 0, 'https://www.booking-wp-plugin.com/demo/advanced-google-calendar/', 'Advanced Google Calendar', 'bookly-addon-advanced-google-calendar', '', 'https://www.booking-wp-plugin.com/add-ons/full-two-way-sync-google-calendar/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-advanced-google-calendar.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-advanced-google-calendar.jpg', 0.00, NULL, 0, 0.00, 0, '2018-06-06 04:37:53', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"With the Advanced Google Calendar (Add-on), you can enjoy a complete bidirectional synchronization between Bookly Calendar and Google Calendar. This ensures that all appointments can be viewed and managed seamlessly in both calendars. Bookings made through Bookly are automatically synced to your Google Calendar, and any new events, updates, or cancellations made in your Google Calendar are instantly reflected in Bookly.\",\"tags\":[\"Calendar & Sync\",\"Integrations\",\"Automation\"],\"short\":\"Two-way sync with staff Google calendars.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":49,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":15.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(15, 21841871, 0, 0, 'https://www.booking-wp-plugin.com/demo/google-maps-address/', 'Google Maps Address', 'bookly-addon-google-maps-address', '', 'https://www.booking-wp-plugin.com/add-ons/google-maps-autocomplete-service/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-google-maps-address.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-google-maps-address.jpg', 0.00, NULL, 0, 0.00, 0, '2018-04-29 02:45:11', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"The Bookly Google Maps Address (Add-on) streamlines the process of filling out address details in the booking form by using the Google Maps autocomplete service. Clients can quickly choose an address from the suggestions that appear as they type, minimizing errors and saving time. Address details entered in the Bookly booking form will be automatically saved in the Customers section for future reference.\",\"tags\":[\"Booking form\",\"Integrations\"],\"short\":\"Autocomplete and validate customer addresses.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(16, 21841856, 0, 0, 'https://www.booking-wp-plugin.com/demo/invoices/', 'Invoices', 'bookly-addon-invoices', '', 'https://www.booking-wp-plugin.com/add-ons/automatic-invoicing/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-invoices.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-invoices.jpg', 0.00, NULL, 0, 0.00, 0, '2018-04-29 02:30:22', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Invoices (Add-on) allows you to automatically generate invoices for your clients upon ordered appointments in Bookly. You can choose to send payment requests when appointments are booked, approved, or received, and set a specific payment period. This feature allows you to quickly and easily collect payment from your clients and improve your cash flow.\",\"tags\":[\"Payments\",\"Automation\",\"Customers\"],\"short\":\"Automatic PDF invoices on your own template.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(17, 21841828, 0, 0, 'https://www.booking-wp-plugin.com/demo/taxes/', 'Taxes', 'bookly-addon-taxes', '', 'https://www.booking-wp-plugin.com/add-ons/automated-tax-calculations/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-taxes.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-taxes.jpg', 0.00, NULL, 0, 0.00, 0, '2018-04-29 02:29:54', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Taxes (Add-on) makes it easy for you to include taxes in your service price. You can define multiple tax rates and apply them to selected services in Bookly. Once you\\u2019ve set up the tax rates, Bookly will automatically calculate and add the appropriate tax amount to the service price, resulting in a final price that includes taxes.\",\"tags\":[\"Payments\",\"Automation\"],\"short\":\"Per-service tax rates, included or added on top.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(18, 21841764, 0, 0, 'https://www.booking-wp-plugin.com/demo/cart/', 'Cart', 'bookly-addon-cart', '', 'https://www.booking-wp-plugin.com/add-ons/shopping-cart/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-cart.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-cart.jpg', 0.00, NULL, 0, 0.00, 0, '2018-04-29 02:25:40', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do you want to boost your online sales even more? With With the Bookly Cart (Add-on), you can prompt your clients to book more appointments on your website. This feature enables clients to add multiple services to their cart and book them all in a single session. This way, clients can schedule additional future appointments with your business in one go. Also, the Cart step in Bookly can be customized to display summary information in a format that suits your needs.\",\"tags\":[\"Booking form\",\"Payments\"],\"short\":\"Book several services in a single checkout.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(19, 21574566, 0, 0, 'https://www.booking-wp-plugin.com/demo/ratings/', 'Ratings', 'bookly-addon-ratings', '', 'https://www.booking-wp-plugin.com/add-ons/add-staff-ratings/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-ratings.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-ratings.jpg', 0.00, NULL, 0, 0.00, 0, '2018-03-13 06:19:21', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Gathering feedback from customers is crucial for businesses to understand areas where they can improve their services. With the Bookly Ratings (Add-on), you can request feedback from clients after each appointment. By encouraging customers to rate the service they received, you can continuously strive to maintain high professional standards and meet their expectations.\",\"tags\":[\"Customers\",\"Marketing\"],\"short\":\"Collect reviews after the appointment ends.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(20, 21574466, 0, 0, 'https://www.booking-wp-plugin.com/demo/customer-information/', 'Customer Information', 'bookly-addon-customer-information', '', 'https://www.booking-wp-plugin.com/add-ons/add-custom-data-clients-profile/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-customer-information.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-customer-information.jpg', 0.00, NULL, 0, 0.00, 0, '2018-03-13 06:10:12', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Need specific fields or records on a client profile in Bookly? Bookly Customer Information (Add-on) allows you to create multiple custom fields of different types that will appear on the Details step of the booking form. Once a booking is complete, the custom information entered by the client will be added to their profile in Bookly for future reference.\",\"tags\":[\"Customers\",\"Booking form\"],\"short\":\"Extra profile fields kept with every client.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(21, 21574371, 0, 0, 'https://www.booking-wp-plugin.com/demo/compound-services/', 'Compound Services', 'bookly-addon-compound-services', '', 'https://www.booking-wp-plugin.com/add-ons/group-services-complex-appointments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-compound-services.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-compound-services.jpg', 0.00, NULL, 0, 0.00, 0, '2018-03-13 06:08:47', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"With the Bookly Compound Services (Add-on), you can combine existing services with spare time to create a separate complex service that clients can book a complete appointment with multiple services as any regular appointment. Each service included in the compound appointment will be performed by a relevant staff member who will only be reserved for their part of the service.\",\"tags\":[\"Booking form\",\"Staff & Teams\"],\"short\":\"Bundle several services into one bookable item.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(22, 21344354, 0, 0, 'https://www.booking-wp-plugin.com/demo/files/', 'Files', 'bookly-addon-files', '', 'https://www.booking-wp-plugin.com/add-ons/attach-files-booking-form/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-files.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-files.jpg', 0.00, NULL, 0, 0.00, 0, '2018-02-01 02:07:58', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"File uploading feature simplifies the process of collecting information required for appointments. Bookly Files (Add-on) makes it possible for the clients to attach files related to their visit directly in the Bookly online booking form. All uploaded files will be available for review and update in the booking details. Important: Bookly Files (Add-on) requires Bookly Custom Fields (Add-on) installed and activated.\",\"tags\":[\"Booking form\",\"Customers\"],\"short\":\"Collect attachments with each appointment.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(23, 21344290, 0, 0, 'https://www.booking-wp-plugin.com/demo/customer-groups/', 'Customer Groups', 'bookly-addon-customer-groups', '', 'https://www.booking-wp-plugin.com/add-ons/organize-clients-groups/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-customer-groups.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-customer-groups.jpg', 0.00, NULL, 0, 0.00, 0, '2018-02-01 02:03:48', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"The Bookly Customer Groups (Add-on) allows you to easily create and manage customer groups in Bookly, giving you the ability to set specific rules for each group. By categorizing your clients, you can control how their bookings are processed, set customized pricing for their appointments, and determine which services are visible to them in the Bookly booking form.\",\"tags\":[\"Customers\",\"Marketing\"],\"short\":\"Group-level discounts and visibility rules.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(24, 21344225, 0, 0, 'https://www.booking-wp-plugin.com/demo/group-booking/', 'Group Booking', 'bookly-addon-group-booking', '', 'https://www.booking-wp-plugin.com/add-ons/accept-group-bookings/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-group-booking.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-group-booking.jpg', 0.00, NULL, 0, 0.00, 0, '2018-02-01 01:33:45', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Group Booking (Add-on) allows clients to book appointments for multiple people at the same time. The add-on enables you to set the minimum and maximum capacity of the service and accept group bookings for the same appointment slot. In the Bookly booking form, clients can specify the number of people they are booking for, and Bookly ensures that the service provider can accommodate the group.\",\"tags\":[\"Booking form\",\"Customers\"],\"short\":\"Several attendees on a single time slot.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
(25, 21114146, 0, 0, '', 'Stripe', 'bookly-addon-stripe', '', 'https://www.booking-wp-plugin.com/add-ons/stripe-payments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-stripe.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-stripe.jpg', 0.00, NULL, 0, 0.00, 0, '2017-12-12 10:46:42', 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Stripe (Add-on) enables your customers to easily and securely pay for their appointments without being redirected away from the Bookly booking form. By integrating the Stripe payment solution into your Bookly PRO booking form, you can streamline the payment process for your customers, making it quick and convenient to complete transactions.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"Card payments through Stripe at booking time.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, 1, '2026-10-11 06:59:24'),
