nt;\\n    border: 1.5px solid #e2e8f0 !important;\\n    border-radius: 30px !important;\\n    font-weight: 600 !important;\\n    padding: 10px 20px !important;\\n}\\n\\n/* Apple: \\u0110en tuy\\u1ec1n */\\n.bookly-form .bookly-js-calendar-button.apple,\\n.bookly-form a.bookly-calendar-button[href*=\\\"apple\\\"],\\n.bookly-form .bookly-sync-apple {\\n    background-color: #000000 !important;\\n    color: #ffffff !important;\\n    border-radius: 30px !important;\\n    border: none !important;\\n    font-weight: 600 !important;\\n    padding: 10px 20px !important;\\n}\\n\\n/* Outlook: Xanh d\\u01b0\\u01a1ng Microsoft */\\n.bookly-form .bookly-js-calendar-button.outlook,\\n.bookly-form a.bookly-calendar-button[href*=\\\"outlook\\\"],\\n.bookly-form .bookly-sync-outlook {\\n    background-color: #0078d4 !important;\\n    color: #ffffff !important;\\n    border-radius: 30px !important;\\n    border: none !important;\\n    font-weight: 600 !important;\\n    padding: 10px 20px !important;\\n}\\n\\n/* Yahoo: T\\u00edm \\u0111\\u1eb7c tr\\u01b0ng */\\n.bookly-form .bookly-js-calendar-button.yahoo,\\n.bookly-form a.bookly-calendar-button[href*=\\\"yahoo\\\"],\\n.bookly-form .bookly-sync-yahoo {\\n    background-color: #6001d2 !important;\\n    color: #ffffff !important;\\n    border-radius: 30px !important;\\n    border: none !important;\\n    font-weight: 600 !important;\\n    padding: 10px 20px !important;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-10-14 15:15:35\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'b63489dc-d5da-4d51-80c2-f52c39648ff8', '', '', '2026-10-14 15:15:35', '2026-10-14 15:15:35', '', 0, 'http://localhost/dongphuc/b63489dc-d5da-4d51-80c2-f52c39648ff8/', 0, 'customize_changeset', '', 0);
INSERT INTO `dp5_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(102, 1, '2026-10-14 15:15:35', '2026-10-14 15:15:35', '/* ===================================================\n   1. TỐI ƯU THANH TIẾN TRÌNH (5 BƯỚC) THÀNH NÚT BO TRÒN\n   =================================================== */\n.bookly-form .bookly-progress-tracker,\n.ast-main-site-wrap .bookly-form .bookly-progress-tracker {\n    display: flex !important;\n    justify-content: space-between !important;\n    gap: 8px !important;\n    border: none !important;\n    background: transparent !important;\n    margin-bottom: 25px !important;\n}\n\n.bookly-form .bookly-progress-tracker > div {\n    flex: 1 !important;\n    text-align: center !important;\n    padding: 12px 14px !important;\n    border-radius: 30px !important;\n    background-color: #f1f5f9 !important;\n    color: #64748b !important;\n    font-weight: 600 !important;\n    font-size: 13px !important;\n    border: none !important;\n    position: relative !important;\n    box-shadow: none !important;\n}\n\n/* Xóa vạch kẻ ngang mặc định của Bookly */\n.bookly-form .bookly-progress-tracker > div > div,\n.bookly-form .bookly-progress-tracker > div::after,\n.bookly-form .bookly-progress-tracker > div::before {\n    display: none !important;\n    background: none !important;\n    height: 0 !important;\n}\n\n/* Trạng thái bước đang chọn hoặc hoàn thành (Màu xanh chủ đạo) */\n.bookly-form .bookly-progress-tracker > div.active,\n.bookly-form .bookly-progress-tracker > div.completed {\n    background-color: #5c6ac4 !important;\n    color: #ffffff !important;\n}\n\n\n/* ===================================================\n   2. BO TRÒN Ô NHẬP LIỆU, DROPDOWN, TEXTAREA\n   =================================================== */\n.bookly-form input[type=\"text\"],\n.bookly-form input[type=\"tel\"],\n.bookly-form input[type=\"email\"],\n.bookly-form select,\n.bookly-form textarea,\n.bookly-form .bookly-select {\n    border-radius: 12px !important;\n    border: 1.5px solid #e2e8f0 !important;\n    padding: 12px 16px !important;\n    background-color: #ffffff !important;\n    font-size: 14px !important;\n    color: #1e293b !important;\n}\n\n.bookly-form input:focus,\n.bookly-form select:focus,\n.bookly-form textarea:focus {\n    border-color: #5c6ac4 !important;\n    outline: none !important;\n    box-shadow: 0 0 0 3px rgba(92, 106, 196, 0.15) !important;\n}\n\n\n/* ===================================================\n   3. NÚT ĐIỀU HƯỚNG (< VÀ > HOẶC TIẾP THEO)\n   =================================================== */\n.bookly-form button,\n.bookly-form .bookly-btn,\n.bookly-form .bookly-next-step,\n.bookly-form .bookly-prev-step {\n    border-radius: 30px !important;\n    background-color: #5c6ac4 !important;\n    color: #ffffff !important;\n    border: none !important;\n    font-weight: 600 !important;\n    padding: 12px 24px !important;\n    box-shadow: 0 4px 12px rgba(92, 106, 196, 0.25) !important;\n}\n\n.bookly-form button:hover,\n.bookly-form .bookly-btn:hover {\n    background-color: #4c58b0 !important;\n}\n\n\n/* ===================================================\n   4. ĐỒNG BỘ MÀU CHUẨN XÁC CÁC NÚT LỊCH Ở BƯỚC CUỐI (ẢNH 5)\n   =================================================== */\n/* Google: Nền trắng, viền xám nhẹ, chữ tối */\n.bookly-form .bookly-js-calendar-button.google,\n.bookly-form a.bookly-calendar-button[href*=\"google\"],\n.bookly-form .bookly-sync-google {\n    background-color: #ffffff !important;\n    color: #374151 !important;\n    border: 1.5px solid #e2e8f0 !important;\n    border-radius: 30px !important;\n    font-weight: 600 !important;\n    padding: 10px 20px !important;\n}\n\n/* Apple: Đen tuyền */\n.bookly-form .bookly-js-calendar-button.apple,\n.bookly-form a.bookly-calendar-button[href*=\"apple\"],\n.bookly-form .bookly-sync-apple {\n    background-color: #000000 !important;\n    color: #ffffff !important;\n    border-radius: 30px !important;\n    border: none !important;\n    font-weight: 600 !important;\n    padding: 10px 20px !important;\n}\n\n/* Outlook: Xanh dương Microsoft */\n.bookly-form .bookly-js-calendar-button.outlook,\n.bookly-form a.bookly-calendar-button[href*=\"outlook\"],\n.bookly-form .bookly-sync-outlook {\n    background-color: #0078d4 !important;\n    color: #ffffff !important;\n    border-radius: 30px !important;\n    border: none !important;\n    font-weight: 600 !important;\n    padding: 10px 20px !important;\n}\n\n/* Yahoo: Tím đặc trưng */\n.bookly-form .bookly-js-calendar-button.yahoo,\n.bookly-form a.bookly-calendar-button[href*=\"yahoo\"],\n.bookly-form .bookly-sync-yahoo {\n    background-color: #6001d2 !important;\n    color: #ffffff !important;\n    border-radius: 30px !important;\n    border: none !important;\n    font-weight: 600 !important;\n    padding: 10px 20px !important;\n}', 'astra-child', '', 'inherit', 'closed', 'closed', '', '65-revision-v1', '', '', '2026-10-14 15:15:35', '2026-10-14 15:15:35', '', 65, 'http://localhost/dongphuc/?p=102', 0, 'revision', '', 0),
